// Inter (SIL Open Font License 1.1, see ../assets/fonts/LICENSE-Inter.txt), cut down for report PDFs.
//
// jsPDF's built-in Helvetica has no rupee sign and no true minus: every "₹" in a report PDF came out
// as "¹" and every "−" as a stray quote. These two static weights (Regular 400, SemiBold 600) were
// made from the app's own Inter files (assets/fonts/inter-latin*.woff2, the variable font pinned to
// one weight, merged, and subset to Latin-1 plus ₹ – — • … − × · and curly quotes), about 33 KB
// each, so a report stays far under the 25 MB body limit WhatsApp sending goes through.
// Regenerate with fontTools (varLib.instancer + merge + subset) if more characters are ever needed.

export const REPORT_FONT_FAMILY = "PepInter";

const INTER_REGULAR_TTF_BASE64 = "";
const INTER_SEMIBOLD_TTF_BASE64 = "";

/**
 * Adds the two weights to a jsPDF document. Returns the family name to use, or "helvetica" when the
 * document refuses the font (an older jsPDF), so a report still prints rather than failing.
 */
export const installReportFonts = (doc) => {
  try {
    doc.addFileToVFS("PepInter-Regular.ttf", INTER_REGULAR_TTF_BASE64);
    doc.addFont("PepInter-Regular.ttf", REPORT_FONT_FAMILY, "normal");
    doc.addFileToVFS("PepInter-SemiBold.ttf", INTER_SEMIBOLD_TTF_BASE64);
    doc.addFont("PepInter-SemiBold.ttf", REPORT_FONT_FAMILY, "bold");
    doc.setFont(REPORT_FONT_FAMILY, "normal");
    return REPORT_FONT_FAMILY;
  } catch {
    return "helvetica";
  }
};
